from collections import deque
from typing import Dict

def solution() -> Dict[int, str]:
    graph = {
        1: [3, 4],
        2: [3],
        3: [1, 2, 6],
        4: [1, 5],
        5: [4],
        6: [3],
    }

    labels = ['A', 'B']
    color_index = {}

    for start in graph:
        if start in color_index:
            continue

        color_index[start] = 0
        q = deque([start])

        while q:
            u = q.popleft()
            for v in graph[u]:
                if v not in color_index:
                    color_index[v] = 1 - color_index[u]
                    q.append(v)
                elif color_index[v] == color_index[u]:
                    raise ValueError('Graph is not 2-colorable')

    return {v: labels[color_index[v]] for v in sorted(graph)}

