def solution() -> int:
    # Determine whether the origin (0, 0) lies inside the convex hull
    # of the given points using a Jarvis-march-built hull and a
    # point-in-convex-polygon test.

    points = [
        (-1.871, -0.592),
        (-0.268, -1.208),
        (-1.421, -1.07),
        (-1.397, -0.404),
        (-1.337, 0.695),
        (-1.17, -1.526),
        (-0.492, 0.203),
        (0.459, -0.371),
    ]

    def orientation(p, q, r):
        # Cross product of vectors pq and pr
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])

    def dist2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    def jarvis_march(pts):
        n = len(pts)
        if n < 3:
            return pts[:]

        leftmost = min(range(n), key=lambda i: (pts[i][0], pts[i][1]))
        hull = []
        p = leftmost

        while True:
            hull.append(pts[p])
            q = (p + 1) % n
            for r in range(n):
                val = orientation(pts[p], pts[q], pts[r])
                if val > 0 or (val == 0 and dist2(pts[p], pts[r]) > dist2(pts[p], pts[q])):
                    q = r
            p = q
            if p == leftmost:
                break
        return hull

