def solution() -> dict:
    participants = {
        0: {'available_slots': [0, 1, 3], 'meetings': [0]},
        1: {'available_slots': [0, 1, 2, 3], 'meetings': [1, 0]},
        2: {'available_slots': [0, 1, 2, 3], 'meetings': [0]}
    }
    meetings = [0, 1]

    # Build attendees per meeting
    attendees = {m: [] for m in meetings}
    for p, info in participants.items():
        for m in info['meetings']:
            attendees[m].append(p)

    # Find feasible slots for each meeting as intersection of attendees' availability
    feasible = {}
    for m in meetings:
        common = None
        for p in attendees[m]:
            slots = set(participants[p]['available_slots'])
            common = slots if common is None else common & slots
        feasible[m] = sorted(common) if common is not None else []

    # Backtracking search to assign one slot per meeting with no participant conflicts
    assignment = {}

    def share_participant(m1, m2):
        return len(set(attendees[m1]) & set(attendees[m2])) > 0

    ordered_meetings = sorted(meetings, key=lambda m: len(feasible[m]))

    def backtrack(i):
        if i == len(ordered_meetings):
            return True
        m = ordered_meetings[i]
        for t in feasible[m]:
            conflict = False
            for om, ot in assignment.items():
                if ot == t and share_participant(m, om):
                    conflict = True
                    break
            if not conflict:
                assignment[m] = t
                if backtrack(i + 1):
                    return True
                del assignment[m]
        return False

    backtrack(0)
    return {m: [assignment[m]] for m in sorted(assignment)}

