from typing import Dict, List

def solution() -> Dict[int, List[int]]:
    participants = {
        0: {"available_slots": [1, 3], "meetings": [1]},
        1: {"available_slots": [0, 1], "meetings": [0, 1]},
        2: {"available_slots": [0, 1, 2, 3], "meetings": [1]},
    }

    meetings = sorted({m for info in participants.values() for m in info["meetings"]})

    feasible = {}
    for m in meetings:
        attendees = [pid for pid, info in participants.items() if m in info["meetings"]]
        common = set(participants[attendees[0]]["available_slots"])
        for pid in attendees[1:]:
            common &= set(participants[pid]["available_slots"])
        feasible[m] = sorted(common)

    conflict_pairs = set()
    for info in participants.values():
        ms = info["meetings"]
        for i in range(len(ms)):
            for j in range(i + 1, len(ms)):
                a, b = sorted((ms[i], ms[j]))
                conflict_pairs.add((a, b))

    order = sorted(meetings, key=lambda m: len(feasible[m]))
    assignment = {}

    def backtrack(idx: int) -> bool:
        if idx == len(order):
            return True
        m = order[idx]
        for t in feasible[m]:
            ok = True
            for other_m, other_t in assignment.items():
                if t == other_t and tuple(sorted((m, other_m))) in conflict_pairs:
                    ok = False
                    break
            if ok:
                assignment[m] = t
                if backtrack(idx + 1):
                    return True
                del assignment[m]
        return False

    if not backtrack(0):
        raise ValueError("No feasible schedule found")

    return {m: [assignment[m]] for m in sorted(assignment)}

