def solution() -> Dict[int, List[int]]:
    participants = {
        0: {"available_slots": [2, 3], "meetings": [1]},
        1: {"available_slots": [0, 2], "meetings": [1, 0]},
        2: {"available_slots": [0, 2, 3], "meetings": [1]},
    }

    meeting_to_participants = {}
    for participant, info in participants.items():
        for meeting in info["meetings"]:
            meeting_to_participants.setdefault(meeting, []).append(participant)

    meeting_domains = {}
    attendee_sets = {}
    for meeting, plist in meeting_to_participants.items():
        common_slots = set(participants[plist[0]]["available_slots"])
        for participant in plist[1:]:
            common_slots &= set(participants[participant]["available_slots"])
        meeting_domains[meeting] = sorted(common_slots)
        attendee_sets[meeting] = set(plist)
        if not meeting_domains[meeting]:
            return {}

    ordered_meetings = sorted(meeting_to_participants.keys(), key=lambda m: (len(meeting_domains[m]), m))
    assignment = {}

    def backtrack(index: int) -> bool:
        if index == len(ordered_meetings):
            return True

        meeting = ordered_meetings[index]
        for slot in meeting_domains[meeting]:
            valid = True
            for other_meeting, other_slot in assignment.items():
                if other_slot == slot and (attendee_sets[meeting] & attendee_sets[other_meeting]):
                    valid = False
                    break

            if not valid:
                continue

            assignment[meeting] = slot
            if backtrack(index + 1):
                return True
            del assignment[meeting]

        return False

    if not backtrack(0):
        return {}

    return {meeting: [assignment[meeting]] for meeting in sorted(assignment)}

