        if idx == len(meetings):
            return True
        m = meetings[idx]
        for s in feasible[m]:
            if consistent(m, s):
                assignment[m] = s
                if backtrack(idx + 1):
                    return True
                del assignment[m]
        return False

    backtrack(0)
    return {m: [assignment[m]] for m in meetings}

