from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    n = 4
    edges = [
        (2, 1, 5),
        (2, 3, 4),
        (1, 3, 2),
        (1, 0, 6),
        (0, 2, 2),
    ]
    start, end = 0, 3

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {i: float("inf") for i in range(n)}
    prev = {i: None for i in range(n)}
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        if u == end:
            break
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(pq, (nd, v))

    if dist[end] == float("inf"):
        return [], -1

    path = []
    cur = end
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()

    return path, int(dist[end])

